<?php
namespace App\Controllers\Api\V1;
use App\Core\ApiController; use App\Services\Communication\NotificationTemplateService; use App\Validation\NotificationTemplateValidation; use Throwable;
class NotificationTemplateController extends ApiController { public function __construct(private readonly NotificationTemplateService $service=new NotificationTemplateService()){} public function index(){try{return $this->ok('Notification template listesi getirildi',$this->service->list($this->request->getGet()));}catch(Throwable $e){return $this->failFromException($e);}} public function create(){try{$p=$this->apiValidator->validateOrFail($this->request->getJSON(true)??[],NotificationTemplateValidation::createRules()); return $this->ok('Notification template olusturuldu',$this->service->create($p));}catch(Throwable $e){return $this->failFromException($e);}} public function show($id=null){try{return $this->ok('Notification template getirildi',$this->service->show((int)$id));}catch(Throwable $e){return $this->failFromException($e);}} public function update($id=null){try{$p=$this->apiValidator->validateOrFail($this->request->getJSON(true)??[],NotificationTemplateValidation::updateRules()); return $this->ok('Notification template guncellendi',$this->service->update((int)$id,$p));}catch(Throwable $e){return $this->failFromException($e);}} public function delete($id=null){try{$this->service->delete((int)$id); return $this->ok('Notification template silindi');}catch(Throwable $e){return $this->failFromException($e);}} }
